package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class TypeHandler_createValueTest {

    @Test
    void testCreateValue_withStringClass_returnsSameString() throws Exception {
        Object result = TypeHandler.createValue("hello", String.class);
        assertEquals("hello", result);
    }

    @Test
    void testCreateValue_withIntegerClass_parsesInteger() throws Exception {
        Object result = TypeHandler.createValue("42", Integer.class);
        assertEquals(Integer.valueOf(42), result);
    }

    @Test
    void testCreateValue_withIntegerClass_parsesHexInteger() throws Exception {
        Object result = TypeHandler.createValue("0x2A", Integer.class);
        assertEquals(Integer.valueOf(42), result);
    }

    @Test
    void testCreateValue_withIntegerClass_invalid_throwsParseException() {
        assertThrows(ParseException.class, () -> TypeHandler.createValue("notANumber", Integer.class));
    }

    @Test
    void testCreateValue_withNonClassArgument_throwsClassCastException() {
        assertThrows(ClassCastException.class, () -> TypeHandler.createValue("abc", new Object()));
    }
}

